const S2=async k=>{const r=await q('SELECT value FROM settings WHERE key=$1',[k]);return r.rowCount?r.rows[0].value:null};
const rcpt=id=>'NF-'+String(id).padStart(6,'0');
async function reminders(force){
 if(!force&&(await S2('reminders_on'))!=='1')return 0;
 const d=parseInt(await S2('reminder_days'),10)||3;let n=0;
 const g=await q("SELECT id,name,end_date::text AS e,(end_date-current_date) AS days_left FROM groups WHERE end_date IS NOT NULL AND end_date>=current_date AND end_date<=current_date+$1::int",[d]);
 for(const x of g.rows){const ref='rappel-'+x.id+'-'+x.e;
  if((await q('SELECT 1 FROM messages WHERE ref=$1',[ref])).rowCount)continue;
  await q("INSERT INTO messages(kind,title,body,group_id,ref) VALUES('alert',$1,$2,$3,$4)",['Rappel : fin de la tontine '+x.name+' dans '+x.days_left+' jour(s)','Pensez à préparer votre cotisation avant le '+x.e+'.',x.id,ref]);n++}
 return n}
