const DRX=/^\d{4}-\d{2}-\d{2}$/;
const fw=(Q,a,dc)=>{const w=[],p=[];const add=(c,v)=>{p.push(v);w.push(c.replace('?','$'+p.length))};
 if(DRX.test(Q.from||''))add(dc+'>=?::date',Q.from);
 if(DRX.test(Q.to||''))add(dc+'<(?::date+1)',Q.to);
 const g=parseInt(Q.group,10);if(g)add(a+'.group_id=?',g);
 if(['Orange Money','MTN Money','Wave'].includes(Q.method))add(a+'.method=?',Q.method);
 return{w,p}};
const AND=a=>a.length?' AND '+a.join(' AND '):'',WH=a=>a.length?' WHERE '+a.join(' AND '):'';
async function journal(Q,lim){
 const F=fw(Q,'p','p.created'),G=fw(Q,'o','o.created');
 const a=await q("SELECT p.id,'Cotisation' AS type,p.created AS at,u.name AS member,g.name AS group_name,p.method,p.amount,p.status FROM payments p JOIN users u ON u.id=p.user_id JOIN groups g ON g.id=p.group_id"+WH(F.w)+' ORDER BY p.created DESC LIMIT '+lim,F.p);
 const b=await q("SELECT o.id,'Versement' AS type,o.created AS at,o.beneficiary AS member,g.name AS group_name,o.method,o.amount,CASE o.status WHEN 'paid' THEN 'validated' ELSE o.status END AS status FROM payouts o JOIN groups g ON g.id=o.group_id"+WH(G.w)+' ORDER BY o.created DESC LIMIT '+lim,G.p);
 let r=a.rows.concat(b.rows).sort((x,y)=>new Date(y.at)-new Date(x.at));
 if(Q.status)r=r.filter(x=>x.status===Q.status);
 return r.slice(0,lim)}
app.get('/api/admin/overview',adm,h(async(req,res)=>{const Q=req.query,F=fw(Q,'p','p.created'),G=fw(Q,'o','o.created');
 const sum=async(st,FF)=>(await q('SELECT coalesce(sum(p.amount),0)::int AS v FROM payments p WHERE p.status=$'+(FF.p.length+1)+AND(FF.w),FF.p.concat([st]))).rows[0].v;
 const cur=await sum('validated',F),pend=await sum('pending',F);let pv=null,pp=null;
 if(DRX.test(Q.from||'')&&DRX.test(Q.to||'')){const d1=new Date(Q.from+'T00:00:00Z'),d2=new Date(Q.to+'T00:00:00Z'),days=Math.round((d2-d1)/864e5)+1;
  if(days>0){const f=x=>new Date(x).toISOString().slice(0,10);const PF=fw({...Q,from:f(d1-days*864e5),to:f(d1-864e5)},'p','p.created');pv=await sum('validated',PF);pp=await sum('pending',PF)}}
 const po=async st=>(await q('SELECT coalesce(sum(o.amount),0)::int AS v FROM payouts o WHERE o.status=$'+(G.p.length+1)+AND(G.w),G.p.concat([st]))).rows[0].v;
 const prep=await po('pending'),paid=await po('paid');
 const mp=await q("SELECT to_char(date_trunc('month',p.created),'YYYY-MM') AS m,coalesce(sum(CASE WHEN p.status='validated' THEN p.amount END),0)::int AS v FROM payments p"+WH(F.w)+' GROUP BY 1 ORDER BY 1',F.p);
 const mo=await q("SELECT to_char(date_trunc('month',o.created),'YYYY-MM') AS m,coalesce(sum(CASE WHEN o.status='paid' THEN o.amount END),0)::int AS v FROM payouts o"+WH(G.w)+' GROUP BY 1 ORDER BY 1',G.p);
 const sp=await q('SELECT p.status,count(*)::int AS n FROM payments p'+WH(F.w)+' GROUP BY 1',F.p);
 const so=await q('SELECT o.status,count(*)::int AS n FROM payouts o'+WH(G.w)+' GROUP BY 1',G.p);
 const st={validated:0,pending:0,refused:0,cancelled:0};for(const x of sp.rows)st[x.status]=(st[x.status]||0)+x.n;for(const x of so.rows){const k=x.status==='paid'?'validated':x.status;st[k]=(st[k]||0)+x.n}
 const nt=await q("SELECT (SELECT count(*) FROM payments WHERE status='pending')::int AS pay,(SELECT count(*) FROM users WHERE role='member' AND status='pending')::int AS mem,(SELECT count(*) FROM payouts WHERE status='pending')::int AS po");
 res.json({kpi:{validated:cur,pending:pend,prevValidated:pv,prevPending:pp,toPrepare:prep,balance:cur-paid},months:{pay:mp.rows,out:mo.rows},status:st,latest:await journal(Q,10),badge:nt.rows[0]})}));
